type userFacadeImpl struct {
	repo Repository
	passwordService PasswordService
}

func (s *userFacadeImpl) Signup(ctx context.Context, request UserRegistrationRequest) (UserView, error) {
	exists, err := s.repo.ExistsByEmail(ctx, request.Email)
	if err != nil {
		return UserView{}, fmt.Errorf("check email existence: %w", err)
	}
	if exists {
		return UserView{}, ErrEmailAlreadyInUse
	}

	exists, err = s.repo.ExistsByUsername(ctx, request.Username)
	if err != nil {
		return UserView{}, fmt.Errorf("check username existence: %w", err)
	}
	if exists {
		return UserView{}, ErrUsernameAlreadyInUse
	}

	encodedPassword, err := s.passwordService.EncodePassword(request.Password)
	if err != nil {
		return UserView{}, fmt.Errorf("encode password: %w", err)
	}

	id := uuid.New().String()
	user := request.ToUser(encodedPassword, id)

	savedUser, err := s.repo.Save(ctx, user)
	if err != nil {
		return UserView{}, fmt.Errorf("save user: %w", err)
	}

	return s.createAuthenticationResponse(savedUser), nil
}

// UserFacade.kt L29-36 → login
func (s *userFacadeImpl) Login(ctx context.Context, request UserAuthenticationRequest) (UserView, error) {
    user, err := s.repo.FindByEmail(ctx, request.Email)
    if errors.Is(err, ErrNotFound) {
        return UserView{}, fmt.Errorf("login: user not found")
    }
    if err != nil {
        return UserView{}, fmt.Errorf("login: %w", err)
    }
    if !s.passwordService.Matches(request.Password, user.EncodedPassword) {
        return UserView{}, InvalidRequestError{"Password", "invalid"}
    }
    return s.createAuthenticationResponse(user)
}

