func (s *userFacadeImpl) UpdateUser(ctx context.Context, request UpdateUserRequest, user *User) error {
    if request.Bio != nil {
        user.Bio = *request.Bio
    }
    if request.Image != nil {
        user.Image = *request.Image
    }
    if request.Password != nil {
        encodedPassword, err := s.passwordService.EncodePassword(*request.Password)
        if err != nil {
            return fmt.Errorf("encode password: %w", err)
        }
        user.EncodedPassword = encodedPassword
    }
    if request.Username != nil {
        if err := s.updateUsername(ctx, user, *request.Username); err != nil {
            return fmt.Errorf("update username: %w", err)
        }
    }
    if request.Email != nil {
        if err := s.updateEmail(ctx, user, *request.Email); err != nil {
            return fmt.Errorf("update email: %w", err)
        }
    }
    return nil
}

