func (s *userFacadeImpl) Follow(ctx context.Context, username string, futureFollower User) (ProfileView, error) {
    userToFollow, err := s.repo.FindByUsername(ctx, username)
    if err != nil {
        return ProfileView{}, fmt.Errorf("find user by username: %w", err)
    }

    futureFollower.Follow(userToFollow)

    if err := s.repo.Save(ctx, futureFollower); err != nil {
        return ProfileView{}, fmt.Errorf("save future follower: %w", err)
    }

    return userToFollow.ToFollowedProfileView(), nil
}

// UserFacade.kt L64-70 → unfollow
func (h *Handler) Unfollow(w http.ResponseWriter, r *http.Request) {
    username := chi.URLParam(r, "username")
    followerID, err := auth.UserIDFromContext(r.Context())
    if err != nil {
        httpx.WriteError(w, http.StatusUnauthorized, "UNAUTHORIZED", "user not authenticated")
        return
    }

    profileView, err := h.svc.Unfollow(r.Context(), username, followerID)
    if errors.Is(err, ErrNotFound) {
        httpx.WriteError(w, http.StatusNotFound, "NOT_FOUND", "user not found")
        return
    }
    if err != nil {
        httpx.WriteInternal(w, r, err)
        return
    }
    httpx.WriteJSON(w, http.StatusOK, profileView)
}

